    # Create a freq dictionary to store the frequency of each element in the array
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the count of pairs to 0
    pair_count = 0

    # Iterate over the frequency dictionary
    for count in freq.values():
        # If the count is even, we can form a pair of two elements
        if count % 2 == 0:
            pair_count += count
        # If the count is odd, we can form a pair of two elements and one element will be left
        else:
            pair_count += count - 1

    # The minimum number of elements that need to be changed is the total length of the array minus the count of pairs
    return n - pair_count

def smallest_change(arr):
    # Create a dictionary to store the frequency of each element
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Calculate the number of elements that need to be changed
    changes = 0
    for count in freq.values():
        # If the count is odd, we need to change (count - 1) / 2 elements
        changes += (count - 1) // 2

    return changes

