def hex_key(num):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    for char in num:
        if char in '01234567':
            n = int(char)
            if is_prime(n):
                count += 1
        elif char.upper() in 'BCD':
            n = int(char.upper(), 16)
            if is_prime(n):
                count += 1
    return count

