def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            result += chr((ord(char) - start + 2*2) % 26 + start)
        else:
            result += char
    return result

