def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

output:
def histogram(test):
    # Split the string into a list of letters
    letters = test.split()

    # If the list is empty, return an empty dictionary
    if not letters:
        return {}

    # Create a dictionary to store the frequency of each letter
    frequency = {}

    # Iterate over each letter in the list
    for letter in letters:
        # If the letter is already in the dictionary, increment its count
        if letter in frequency:
            frequency[letter] += 1
        # If the letter is not in the dictionary, add it with a count of 1
        else:
            frequency[letter] = 1

    # Find the maximum frequency
    max_frequency = max(frequency.values())

    # Create a dictionary to store the letters with the maximum frequency
    max_frequency_letters = {}

    # Iterate over each letter and its frequency in the dictionary
    for letter, freq in frequency.items():
        # If the frequency of the letter is equal to the maximum frequency, add it to the dictionary
        if freq == max_frequency:
            max_frequency_letters[letter] = freq

    # Return the dictionary of letters with the maximum frequency
    return max_frequency_letters

