def match_parens(lst):
    s1, s2 = lst
    stack = []

    for c in s1 + s2:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                stack.append(c)

    return 'Yes' if not stack else 'No'

