def is_sorted(lst):
    if len(lst) == 1:
        return True
    for i in range(len(lst)-1):
        if lst[i] > lst[i+1]:
            return False
        elif lst[i] == lst[i+1]:
            if i == 0 or lst[i-1] != lst[i]:
                return False
    return True

