def prod_signs(arr):
    if not arr:
        return None

    signs = [1 if x > 0 else -1 if x < 0 else 0 for x in arr]
    product_of_signs = 1
    for sign in signs:
        product_of_signs *= sign

    product_of_magnitudes = 1
    for x in arr:
        product_of_magnitudes *= abs(x)

    return product_of_magnitudes * product_of_signs

