def largest_smallest_integers(lst):
    # Separate integers into negative and positive lists
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

    # If list is empty, return None for both values
    if negatives == [] and positives == []:
        return (None, None)

    # If there are no positive integers, return None for the positive integer
    if positives == []:
        return (max(negatives) if negatives else None, None)

    # If there are no negative integers, return the smallest positive integer
    if negatives == []:
        return (None, min(positives))

    # Return the largest negative and smallest positive integer
    return (max(negatives), min(positives))

