def file_name_check(file_name):
    # Check if the file name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into two parts: before and after the dot
    name_before_dot, name_after_dot = file_name.split('.')

    # Check if the name before the dot starts with a latin alphabet letter
    if not name_before_dot[0].isalpha():
        return 'No'

    # Check if the name before the dot is not empty
    if not name_before_dot:
        return 'No'

    # Check if the name after the dot is one of the allowed extensions
    if name_after_dot not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the file name
    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    # If all conditions are met, return 'Yes'
    return 'Yes'

import re

def file_name_check(file_name):
    # Check if the file's name starts with a latin alphabet letter
    if not re.match('^[a-zA-Z]', file_name.split('.')[0]):
        return 'No'

    # Check if there is exactly one dot in the file's name
    if file_name.count('.') != 1:
        return 'No'

    # Check if the substring before the dot is not empty
    if not file_name.split('.')[0]:
        return 'No'

    # Check if the substring after the dot is one of the allowed extensions
    if file_name.split('.')[1] not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the file's name
    if len(re.findall('\d', file_name)) > 3:
        return 'No'

    return 'Yes'

