def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n**0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which returns the value of x if n is a prime number and y otherwise."""
    if is_prime(n):
        return x
    else:
        return y

